package order

import (
	"fmt"
	"time"

	"github.com/witsaba/paca/packages/domain/business"
	"github.com/witsaba/paca/packages/domain/ledger"
)

// RouteID is the identity of a route.
//
// The number is generated by the database: it is the counter of the routes
// and not a number of the order. The type exists so that an identifier
// never travels as a plain integer by accident.
type RouteID int64

// Stop is one stop of the route: the order the agent visits there and what
// the stop costs.
//
// The cost is the money of the stop in whole pesos: the transport to that
// client. It is never negative, and it may be zero: a stop the owner walks
// to costs nothing.
type Stop struct {
	// OrderID is the order the stop is of.
	OrderID ID

	// Cost is what the stop costs, in whole pesos.
	Cost ledger.Amount
}

// StopDefinition is what the agent said about one stop of the route.
//
// It is the candidate the agent read, and the domain decides what may enter
// the book of the business.
type StopDefinition struct {
	// OrderID is the order the stop is of.
	OrderID ID

	// Cost is what the stop costs, in whole pesos.
	Cost ledger.Amount
}

// RouteDefinition is what the agent said about the route of a round.
//
// It is the candidate the agent read, and the domain decides what may enter
// the book of the business.
type RouteDefinition struct {
	// Day is the day of the round the route is of.
	Day ledger.Date

	// Stops are the stops of the route, in the order the agent will visit
	// the clients in.
	Stops []StopDefinition
}

// Route is the route of the round of a day: the stops in the order the
// agent will visit the clients in, and what each one costs.
//
// The TOTAL of the route is derived from the stops: the agent never writes
// it, and the storage never holds it.
type Route struct {
	// ID is the identity of the route. It is empty until the storage
	// writes the row.
	ID RouteID

	// BusinessID is the business that owns the route.
	BusinessID business.ID

	// Day is the day the route is of.
	Day ledger.Date

	// Stops are the stops of the route, in the order the agent will visit
	// the clients in.
	Stops []Stop

	// CreatedAt is the moment the row was created. The storage filled it.
	CreatedAt time.Time

	// UpdatedAt is the moment the row was last written. The storage filled
	// it on insert; whoever updates a row is responsible for it after that.
	UpdatedAt time.Time
}

// Total answers what the route costs: the money of every stop.
//
// The rule of the domain: the total of the route is derived from the stops,
// and it is never typed: the agent does not write it, and the storage does
// not hold it.
func (r Route) Total() ledger.Amount {
	total := ledger.Amount(0)

	for _, one := range r.Stops {
		total += one.Cost
	}

	return total
}

// TheRoute answers the route of the round of a day.
//
// The held are the orders the business holds, the written are the routes the
// business wrote already, and the definition is what the agent computed.
//
// The rules of the domain:
//
//   - the route belongs to a business (ErrMissingBusiness);
//   - the route carries the day of the round (ErrMissingRouteDay);
//   - the route carries at least one stop: a route that visits nobody is
//     not a route (ErrNoStops);
//   - the route of a business and a day is written once: a second route for
//     the same day is refused (ErrRouteAlreadyWritten);
//   - every stop is an order of that business (ErrStopNotAnOrder);
//   - every stop is an order the business still OWES: EVERY open order of
//     the business — the ones that are due on the day of the round and the
//     ones that fell due on an earlier day — and a stop of an order that was
//     delivered already is refused (ErrAlreadyDelivered);
//   - the route visits every order once: the same order in two stops is
//     refused (ErrDuplicateStop), because the total of the route is derived
//     from the stops and counts the money of a stop once per stop;
//   - the cost of a stop is never negative: the money of the book counts
//     whole pesos, and a stop the owner walks to costs nothing
//     (ErrInvalidCost).
func TheRoute(
	own business.ID,
	held []Order,
	written []Route,
	definition RouteDefinition,
) (Route, error) {
	if own <= 0 {
		return Route{}, fmt.Errorf("%w: the route is of the business %d", ErrMissingBusiness, own)
	}

	if definition.Day.Time().IsZero() {
		return Route{}, fmt.Errorf("%w: the route carries no day", ErrMissingRouteDay)
	}

	if len(definition.Stops) == 0 {
		return Route{}, fmt.Errorf("%w: the route carries no stop", ErrNoStops)
	}

	for _, one := range written {
		if one.BusinessID == own && one.Day.Time().Equal(definition.Day.Time()) {
			return Route{}, fmt.Errorf("%w: the business %d wrote the route of %s already",
				ErrRouteAlreadyWritten, own, definition.Day)
		}
	}

	built := make([]Stop, 0, len(definition.Stops))
	visited := make(map[ID]struct{}, len(definition.Stops))

	for _, one := range definition.Stops {
		found, ok := theOrderOfTheBusiness(held, one.OrderID)
		if !ok {
			return Route{}, fmt.Errorf("%w: the stop names the order %d", ErrStopNotAnOrder, one.OrderID)
		}

		if found.BusinessID != own {
			return Route{}, fmt.Errorf("%w: the order %d belongs to the business %d",
				ErrStopNotAnOrder, found.ID, found.BusinessID)
		}

		if !found.IsOpen() {
			return Route{}, fmt.Errorf("%w: the order %d is %q", ErrAlreadyDelivered, found.ID, found.State)
		}

		if one.Cost < 0 {
			return Route{}, fmt.Errorf("%w: the stop carries %d pesos", ErrInvalidCost, one.Cost)
		}

		if _, ok := visited[found.ID]; ok {
			return Route{}, fmt.Errorf("%w: the order %d is visited twice", ErrDuplicateStop, found.ID)
		}

		visited[found.ID] = struct{}{}

		built = append(built, Stop(one))
	}

	return Route{BusinessID: own, Day: definition.Day, Stops: built}, nil
}

// TheDelivery answers the orders the route delivers: the orders of its
// stops, in the delivered state.
//
// The rule of the domain: the route the agent writes back is the round it
// made: writing the route delivers the orders of its stops.
//
// The error is ErrStopNotAnOrder when a stop names an order the business
// does not hold, and ErrAlreadyDelivered when the order was delivered
// already.
func (r Route) TheDelivery(held []Order) ([]Order, error) {
	delivered := make([]Order, 0, len(r.Stops))

	for _, one := range r.Stops {
		found, ok := theOrderOfTheBusiness(held, one.OrderID)
		if !ok {
			return nil, fmt.Errorf("%w: the stop names the order %d", ErrStopNotAnOrder, one.OrderID)
		}

		marked, err := found.Delivered()
		if err != nil {
			return nil, err
		}

		delivered = append(delivered, marked)
	}

	return delivered, nil
}

// TheRouteOfTheDay answers the route the business wrote for that day, and
// whether it wrote one.
//
// The rule of the domain: the route of a business and a day is written once,
// and the round of that day carries the route that was written for it.
func TheRouteOfTheDay(routes []Route, own business.ID, day ledger.Date) (Route, bool) {
	for _, one := range routes {
		if one.BusinessID == own && one.Day.Time().Equal(day.Time()) {
			return one, true
		}
	}

	return Route{}, false
}

// RouteFacts are the facts of a route that the storage holds.
//
// They are the row read back: the domain reads them through its own
// constructor, and the row never decides what a route is.
type RouteFacts struct {
	// ID is the identity of the route.
	ID RouteID

	// BusinessID is the business that owns the route.
	BusinessID business.ID

	// Day is the day the route is of.
	Day ledger.Date

	// Stops are the stops of the route, in the order the agent will visit
	// the clients in.
	Stops []Stop
}

// NewRouteFromFacts builds the route the storage holds.
//
// The rules of the domain hold here too: the route belongs to a business,
// carries the day of the round, carries at least one stop, visits every
// order once, and the cost of every stop is never negative.
//
// The error is ErrMissingBusiness when the route is of no business,
// ErrMissingRouteDay when it carries no day, ErrNoStops when it carries no
// stop, ErrInvalidCost when a stop carries a negative cost,
// ErrStopNotAnOrder when a stop names no order, and ErrDuplicateStop when
// the route visits the same order in two stops.
func NewRouteFromFacts(facts RouteFacts) (Route, error) {
	if facts.BusinessID <= 0 {
		return Route{}, fmt.Errorf("%w: the route is of the business %d", ErrMissingBusiness, facts.BusinessID)
	}

	if facts.Day.Time().IsZero() {
		return Route{}, fmt.Errorf("%w: the route carries no day", ErrMissingRouteDay)
	}

	if len(facts.Stops) == 0 {
		return Route{}, fmt.Errorf("%w: the route carries no stop", ErrNoStops)
	}

	stops := make([]Stop, 0, len(facts.Stops))
	visited := make(map[ID]struct{}, len(facts.Stops))

	for _, one := range facts.Stops {
		if one.OrderID == 0 {
			return Route{}, fmt.Errorf("%w: the stop names no order", ErrStopNotAnOrder)
		}

		if one.Cost < 0 {
			return Route{}, fmt.Errorf("%w: the stop carries %d pesos", ErrInvalidCost, one.Cost)
		}

		if _, ok := visited[one.OrderID]; ok {
			return Route{}, fmt.Errorf("%w: the order %d is visited twice", ErrDuplicateStop, one.OrderID)
		}

		visited[one.OrderID] = struct{}{}

		stops = append(stops, Stop{OrderID: one.OrderID, Cost: one.Cost})
	}

	return Route{
		ID:         facts.ID,
		BusinessID: facts.BusinessID,
		Day:        facts.Day,
		Stops:      stops,
	}, nil
}

// theOrderOfTheBusiness answers the order of the list with that identity.
//
// The rule of the domain: the stops of a route are orders of the business,
// and the domain looks for them among the orders it was given.
func theOrderOfTheBusiness(orders []Order, id ID) (Order, bool) {
	for _, one := range orders {
		if one.ID == id {
			return one, true
		}
	}

	return Order{}, false
}
